from datetime import datetime, timedelta

# Helper functions
def time_to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_time(m: int) -> str:
    h = m // 60
    mins = m % 60
    return f"{h:02d}:{mins:02d}"

def subtract_interval(base, busy):
    """Return list of free intervals after removing busy intervals from base (single interval)."""
    free = []
    start, end = base
    for b_start, b_end in sorted(busy):
        if b_end <= start or b_start >= end:
            continue
        if b_start > start:
            free.append((start, min(b_start, end)))
        start = max(start, b_end)
        if start >= end:
            break
    if start < end:
        free.append((start, end))
    return free

def intersect_intervals(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s + 30 <= e:  # need at least 30 min slot
            result.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return result

# Data definitions
work_start = time_to_min("09:00")
work_end = time_to_min("17:00")
work_interval = (work_start, work_end)

participants = {
    "Joshua": {
        "Monday": [("15:00", "15:30")],
        "Tuesday": [("11:30", "12:00"), ("13:00", "13:30"), ("14:30", "15:00")],
        "Wednesday": [],
