        "Wednesday": [("09:00", "09:30"), ("10:00", "11:00"),
                      ("12:30", "15:30"), ("16:00", "16:30")],
    },
}

# Convert busy times to minute intervals
busy_minutes = {}
for person, days in participants.items():
    busy_minutes[person] = {}
    for day, intervals in days.items():
        busy_minutes[person][day] = [(time_to_min(s), time_to_min(e)) for s, e in intervals]

days_order = ["Monday", "Tuesday", "Wednesday"]
meeting_duration = 30  # minutes

solution = None

for day in days_order:
    # Compute free intervals for each participant on this day
    free_per_person = []
    for person in participants:
        busy = busy_minutes[person].get(day, [])
        free = subtract_interval(work_interval, busy)
        free_per_person.append(free)
    # Intersect free intervals of all participants
    common = free_per_person[0]
    for other in free_per_person[1:]:
        common = intersect_intervals(common, other)
        if not common:
            break
    # Apply preference: avoid Monday before 12:00 if possible
    if day == "Monday":
        filtered = [(s, e) for s, e in common if s >= time_to_min("12:00")]
        if filtered:
            common = filtered
    # Choose earliest slot of required length
    for s, e in sorted(common):
        if e - s >= meeting_duration:
            start = s
            end = s + meeting_duration
            solution = [day, min_to_time(start), min_to_time(end)]
            break
    if solution:
        break

print(solution)

